# More careful bounds checking
def check_adjacent(r, c, grid, start_row=0, end_row=6, start_col=0, end_col=16):
    """Check adjacent cells for 2s around a 2x2 block at (r,c)"""
    adjacent_2s = []

    # Check above (r-1, c through c+1)
    if r-1 >= start_row:
        if c < end_col and grid[r-1][c] == 2:
            adjacent_2s.append(f"up:{r-1},{c}")
        if c+1 < end_col and grid[r-1][c+1] == 2:
            adjacent_2s.append(f"up:{r-1},{c+1}")

    # Check below (r+2, c through c+1)
    if r+2 < end_row:
        if c < end_col and grid[r+2][c] == 2:
            adjacent_2s.append(f"down:{r+2},{c}")
        if c+1 < end_col and grid[r+2][c+1] == 2:
            adjacent_2s.append(f"down:{r+2},{c+1}")

    # Check left (r, r+1, c-1)
    if c-1 >= start_col:
        if r < end_row and grid[r][c-1] == 2:
            adjacent_2s.append(f"left:{r},{c-1}")
        if r+1 < end_row and grid[r+1][c-1] == 2:
            adjacent_2s.append(f"left:{r+1},{c-1}")

    # Check right (r, r+1, c+2)
    if c+2 < end_col:
        if r < end_row and grid[r][c+2] == 2:
            adjacent_2s.append(f"right:{r},{c+2}")
        if r+1 < end_row and grid[r+1][c+2] == 2:
            adjacent_2s.append(f"right:{r+1},{c+2}")

    return adjacent_2s

