def block_3x3_fingerprint(grid, r, c):
    """Return tuple of 3x3 area starting at (r,c)"""
    area = []
    for dr in range(3):
        for dc in range(3):
            rr, cc = r + dr, c + dc
            if 0 <= rr < 7 and 0 <= cc < grid[0].__len__():
                area.append(grid[rr][cc])
            else:
                area.append(-1)  # out of bounds
    return tuple(area)

